import { defineComponent } from 'vue';

import HtpItem from './htp-component.vue';
import { IVueHtpComponent } from '../..';

export default defineComponent({
    name: 'HowToPlayPage',
    components: {
        HtpItem
    },
    data: () => ({
        scale: 1,
        scrollType: 'auto'
    }),
    props: {
        layout: {
            type: Array as () => IVueHtpComponent[],
            required: true,
        },
        scrollable: {
            type: Boolean,
            default: true
        },
        displayTab: {
            type: Number,
            required: true
        },
        tab: {
            type: Number,
            required: true
        },
        showControls: {
            type: Boolean,
            required: true
        }
    },
    watch: {
        displayTab(newVal) {
            if (this.scrollable === false && newVal === this.tab) {
                this.updateScale();
            }
        }
    },
    mounted: function() {
        if (this.scrollable === false) {
            this.scrollType = 'unset';
            this.updateScale();
            window.addEventListener('resize', this.updateScale);
            window.addEventListener('orientationchange', this.updateScale);
        }
    },
    beforeDestroy() {
        if (!this.scrollable) {
            window.removeEventListener('resize', this.updateScale);
            window.removeEventListener('orientationchange', this.updateScale);
        }
    },
    methods: {
        updateScale() {
            this.scale = 1;
            this.$nextTick(() => {
                const container = this.$refs.container;
                const content = this.$refs.content;
                if (!container || !content) return;

                const containerHeight = (container as HTMLDivElement).clientHeight;
                const contentHeight = (content as HTMLDivElement).scrollHeight;

                const newScale = (contentHeight * 0.9) / containerHeight;

                if (this.scale !== newScale) {
                    this.scale = newScale;
                }
            });
        },
        scrollStyle() {
            return {
                transform: `scale(${this.scale})`,
                transformOrigin: 'top center',
                'overflow-y': `${this.scrollType}`
            };
        }
    }
});